  1	/**
  2	 * Notes Collected View — Repo Parallelizer GUI.
  3	 *
  4	 * Two-panel layout:
  5	 *   - Left sidebar: all workspaces grouped by project (collapsible groups).
  6	 *     Workspaces with existing notes are visually distinguished with a
  7	 *     `.has-notes` class on the sidebar item.
  8	 *   - Right main panel: editable note cards for workspaces with non-empty notes.
  9	 *     On initial load only non-empty note cards are rendered.
 10	 *     Clicking a sidebar item for a workspace with a card scrolls to it.
 11	 *     Clicking a sidebar item for a workspace without a card creates a new
 12	 *     empty card and focuses the textarea.
 13	 *     Each card auto-saves after 1000 ms of inactivity (debounce).
 14	 *     Saving an empty note removes the card and clears the sidebar indicator.
 15	 *
 16	 * Data flow:
 17	 *   1. `api.notes.list()` fetches the raw PascalCase `GET /api/notes` response.
 18	 *   2. `normaliseNotesResponse()` converts it to a camelCase
 19	 *      `{ projects: [{ projectId, projectName, workspaces: [{ workspaceId, notes }] }] }`
 20	 *      structure used throughout the view.
 21	 *   3. A `notesMap` (`Map<"${projectId}|${workspaceId}", string>`) mirrors the
 22	 *      current note text in memory, keeping sidebar indicators and newly-created
 23	 *      cards in sync with saves without re-fetching from the server.
 24	 *
 25	 * All dynamic text is set via `textContent` (never `innerHTML`) for XSS safety.
 26	 *
 27	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
 28	 * @param {Object}      _params   - Route params (none for this route).
 29	 */
 30	
 31	import { api }                    from '../api.js';
 32	import { showToast }              from '../components/toast.js';
 33	import { normaliseNotesResponse } from '../utils/normalise.js';
 34	import { APP_NAME_SHORT }         from '../utils/constants.js';
 35	
 36	// ---------------------------------------------------------------------------
 37	// Internal DOM helpers
 38	// ---------------------------------------------------------------------------
 39	
 40	/**
 41	 * Find a note card in the main panel by project + workspace ID using dataset
 42	 * attributes (avoids CSS-escaping concerns with arbitrary ID strings).
 43	 *
 44	 * @param {HTMLElement} mainPanel
 45	 * @param {string}      projectId
 46	 * @param {string}      workspaceId
 47	 * @returns {HTMLElement|null}
 48	 */
 49	function findCard(mainPanel, projectId, workspaceId) {
 50	    for (const card of mainPanel.querySelectorAll('.notes-card')) {
 51	        if (card.dataset.projectId === projectId && card.dataset.workspaceId === workspaceId) {
 52	            return card;
 53	        }
 54	    }
 55	    return null;
 56	}
 57	
 58	/**
 59	 * Find a sidebar list item by project + workspace ID.
 60	 *
 61	 * @param {HTMLElement} sidebar
 62	 * @param {string}      projectId
 63	 * @param {string}      workspaceId
 64	 * @returns {HTMLElement|null}
 65	 */
 66	function findSidebarItem(sidebar, projectId, workspaceId) {
 67	    for (const item of sidebar.querySelectorAll('.notes-sidebar-item')) {
 68	        if (item.dataset.projectId === projectId && item.dataset.workspaceId === workspaceId) {
 69	            return item;
 70	        }
 71	    }
 72	    return null;
 73	}
 74	
 75	// ---------------------------------------------------------------------------
 76	// Empty-state management
 77	// ---------------------------------------------------------------------------
 78	
 79	/**
 80	 * Show or hide the "no notes" empty-state message based on whether the main
 81	 * panel contains any note cards.
 82	 *
 83	 * @param {HTMLElement} mainPanel
 84	 */
 85	function refreshEmptyState(mainPanel) {
 86	    const existing = mainPanel.querySelector('.notes-empty-state');
 87	    const hasCards = mainPanel.querySelector('.notes-card') !== null;
 88	    if (hasCards && existing) {
 89	        existing.remove();
 90	    } else if (!hasCards && !existing) {
 91	        const p = document.createElement('p');
 92	        p.className = 'notes-empty-state';
 93	        p.textContent = 'No workspace notes yet. Click a workspace in the sidebar to add one.';
 94	        mainPanel.appendChild(p);
 95	    }
 96	}
 97	
 98	// ---------------------------------------------------------------------------
 99	// Sidebar builder
100	// ---------------------------------------------------------------------------

101	
102	/**
103	 * Build the left sidebar listing all workspaces grouped by project.
104	 *
105	 * Each project is rendered as a `<details>` element (open by default) so
106	 * groups are collapsible. Sidebar items with existing notes carry the
107	 * `.has-notes` modifier class.
108	 *
109	 * @param {Array<{ projectId: string, projectName: string,
110	 *   workspaces: Array<{ workspaceId: string, notes: string }> }>} projects
111	 * @param {function(string, string): void} onItemClick
112	 *   Called with (projectId, workspaceId) when a sidebar button is clicked.
113	 * @returns {HTMLElement}
114	 */
115	function buildSidebar(projects, onItemClick) {
116	    const aside = document.createElement('aside');
117	    aside.className = 'notes-sidebar';
118	
119	    const heading = document.createElement('h2');
120	    heading.className = 'notes-sidebar-heading';
121	    heading.textContent = 'Workspaces';
122	    aside.appendChild(heading);
123	
124	    for (const project of projects) {
125	        const details = document.createElement('details');
126	        details.className = 'notes-sidebar-group';
127	        details.open = true;
128	
129	        const summary = document.createElement('summary');
130	        summary.className = 'notes-sidebar-group-title';
131	        summary.textContent = project.projectName || project.projectId;
132	        details.appendChild(summary);
133	
134	        const ul = document.createElement('ul');
135	        ul.className = 'notes-sidebar-list';
136	
137	        for (const ws of project.workspaces) {
138	            const li = document.createElement('li');
139	            li.className = 'notes-sidebar-item';
140	            li.dataset.projectId   = project.projectId;
141	            li.dataset.workspaceId = ws.workspaceId;
142	            if (ws.notes) {
143	                li.classList.add('has-notes');
144	            }
145	
146	            const btn = document.createElement('button');
147	            btn.type = 'button';
148	            btn.className = 'notes-sidebar-btn';
149	            btn.textContent = ws.workspaceId;
150	            btn.addEventListener('click', () => onItemClick(project.projectId, ws.workspaceId));
151	
152	            li.appendChild(btn);
153	            ul.appendChild(li);
154	        }
155	
156	        details.appendChild(ul);
157	        aside.appendChild(details);
158	    }
159	
160	    return aside;
161	}
162	
163	// ---------------------------------------------------------------------------
164	// Note card builder
165	// ---------------------------------------------------------------------------
166	
167	/**
168	 * Build a single editable note card for a workspace.
169	 *
170	 * The card header contains a clickable link to the workspace detail view.
171	 * The textarea fires a 1000 ms debounced save on `input` events.
172	 * A status span (aria-live="polite") shows Saving… / Saved / Save failed.
173	 *
174	 * @param {string}   projectId
175	 * @param {string}   projectName
176	 * @param {string}   workspaceId
177	 * @param {string}   initialNotes
178	 * @param {function(string, string, string): Promise<void>} onSave
179	 *   Called with (projectId, workspaceId, notes). Rejects on save failure.
180	 * @param {function(): void} onEmpty
181	 *   Called (after a successful save) when the note text is empty.
182	 * @returns {HTMLElement}
183	 */
184	function buildNoteCard(projectId, projectName, workspaceId, initialNotes, onSave, onEmpty) {
185	    const article = document.createElement('article');
186	    article.className = 'notes-card';
187	    article.dataset.projectId   = projectId;
188	    article.dataset.workspaceId = workspaceId;
189	
190	    // ---- Card header ----
191	    const header = document.createElement('header');
192	    header.className = 'notes-card-header';
193	
194	    const link = document.createElement('a');
195	    link.href = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(workspaceId)}`;
196	    link.className = 'notes-card-ws-link';
197	    // textContent used intentionally: projectName/workspaceId come from the
198	    // server response and must not be treated as markup.
199	    link.textContent = `${projectName || projectId} \u203a ${workspaceId}`;
200	    header.appendChild(link);
201	
202	    const statusEl = document.createElement('span');
203	    statusEl.className = 'notes-card-status';
204	    statusEl.setAttribute('aria-live', 'polite');
205	    statusEl.hidden = true;
206	    header.appendChild(statusEl);
207	
208	    article.appendChild(header);
209	
210	    // ---- Textarea ----
211	    const textarea = document.createElement('textarea');
212	    textarea.className = 'notes-card-textarea';
213	    textarea.value = initialNotes;
214	    textarea.rows = 6;
215	    article.appendChild(textarea);
216	
217	    // ---- Debounced auto-save ----
218	    let debounceTimer = null;
219	
220	    textarea.addEventListener('input', () => {
221	        clearTimeout(debounceTimer);
222	        debounceTimer = setTimeout(async () => {
223	            statusEl.textContent = 'Saving\u2026';
224	            statusEl.hidden = false;
225	            try {
226	                await onSave(projectId, workspaceId, textarea.value);
227	                if (textarea.value === '') {
228	                    onEmpty();
229	                    return;
230	                }
231	                statusEl.textContent = 'Saved';
232	                setTimeout(() => { statusEl.hidden = true; }, 3000);
233	            } catch {
234	                statusEl.textContent = 'Save failed.';
235	            }
236	        }, 1000);
237	    });
238	
239	    return article;
240	}
241	
242	// ---------------------------------------------------------------------------
243	// Public view entry point
244	// ---------------------------------------------------------------------------
245	
246	/**
247	 * Render the Notes Collected view.
248	 *
249	 * Fetches all workspace notes via `api.notes.list()`, normalises the response,
250	 * then builds a two-panel layout: sidebar on the left, scrollable main panel

251	 * on the right.
252	 *
253	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
254	 * @param {Object}      _params   - Route params (none for this route).
255	 */
256	export async function renderNotesCollected(container, _params) {
257	    document.title = 'Notes - ' + APP_NAME_SHORT;
258	
259	    // Show loading state immediately.
260	    const loadingEl = document.createElement('p');
261	    loadingEl.className = 'notes-loading';
262	    loadingEl.textContent = 'Loading notes\u2026';
263	    container.appendChild(loadingEl);
264	
265	    let rawResponse;
266	    /** @type {{ notesColumns?: number, notesCardHeight?: number }} */
267	    let displaySettings;
268	    try {
269	        [rawResponse, displaySettings] = await Promise.all([
270	            api.notes.list(),
271	            api.config.notesDisplay.get().catch(() => ({})),
272	        ]);
273	    } catch (err) {
274	        container.removeChild(loadingEl);
275	        showToast(`Failed to load notes: ${err.message}`, 'error');
276	        const errEl = document.createElement('p');
277	        errEl.className = 'notes-error';
278	        errEl.textContent = 'Could not load workspace notes. Please try again.';
279	        container.appendChild(errEl);
280	        return;
281	    }
282	
283	    container.removeChild(loadingEl);
284	
285	    const { projects } = normaliseNotesResponse(rawResponse);
286	
287	    // ---- In-memory notes map — keeps local state in sync with saves ----
288	    /** @type {Map<string, string>} Key: `${projectId}|${workspaceId}` */
289	    const notesMap = new Map();
290	    for (const project of projects) {
291	        for (const ws of project.workspaces) {
292	            notesMap.set(`${project.projectId}|${ws.workspaceId}`, ws.notes);
293	        }
294	    }
295	
296	    // ---- Layout container ----
297	    const layout = document.createElement('div');
298	    layout.className = 'notes-view';
299	
300	    // ---- Main panel ----
301	    const mainPanel = document.createElement('div');
302	    mainPanel.className = 'notes-main';
303	
304	    // Apply display settings from API (gracefully degrade if fetch failed).
305	    if (displaySettings.notesColumns) {
306	        mainPanel.style.gridTemplateColumns = `repeat(${displaySettings.notesColumns}, 1fr)`;
307	    }
308	    if (displaySettings.notesCardHeight) {
309	        // notesCardHeight is always an integer (pixels) per the NotesDisplayConfig typedef
310	        // (see api.js — @property {number} notesCardHeight, range 120–800), so appending
311	        // 'px' unconditionally is safe. If the API contract changes to include units, remove the suffix.
312	        mainPanel.style.setProperty('--notes-card-height', `${displaySettings.notesCardHeight}px`);
313	    }
314	
315	    // Forward-declare sidebar so handlers can reference it after assignment.
316	    /** @type {HTMLElement} */
317	    let sidebar; // assigned below after handlers are defined
318	
319	    // ---- Shared save handler ----
320	    async function handleSave(projectId, workspaceId, notes) {
321	        await api.workspaces.update(projectId, workspaceId, { notes });
322	        notesMap.set(`${projectId}|${workspaceId}`, notes);
323	        // Update sidebar indicator for non-empty saves.
324	        if (notes) {
325	            findSidebarItem(sidebar, projectId, workspaceId)?.classList.add('has-notes');
326	        }
327	    }
328	
329	    // ---- Handler: note saved as empty → remove card + clear sidebar indicator ----
330	    function handleCardEmpty(projectId, workspaceId) {
331	        const card = findCard(mainPanel, projectId, workspaceId);
332	        if (card) card.remove();
333	
334	        findSidebarItem(sidebar, projectId, workspaceId)?.classList.remove('has-notes');
335	        notesMap.set(`${projectId}|${workspaceId}`, '');
336	        refreshEmptyState(mainPanel);
337	    }
338	
339	    // ---- Sidebar click handler ----
340	    function handleSidebarClick(projectId, workspaceId) {
341	        const existingCard = findCard(mainPanel, projectId, workspaceId);
342	        if (existingCard) {
343	            // Card already exists — scroll to it and focus.
344	            existingCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
345	            existingCard.querySelector('.notes-card-textarea')?.focus();
346	            return;
347	        }
348	
349	        // No card yet — create a new empty one.
350	        const project = projects.find((p) => p.projectId === projectId);
351	        const projectName   = project ? project.projectName : projectId;
352	        const currentNotes  = notesMap.get(`${projectId}|${workspaceId}`) ?? '';
353	
354	        const card = buildNoteCard(
355	            projectId,
356	            projectName,
357	            workspaceId,
358	            currentNotes,
359	            handleSave,
360	            () => handleCardEmpty(projectId, workspaceId),
361	        );
362	
363	        mainPanel.appendChild(card);
364	        refreshEmptyState(mainPanel);
365	        card.scrollIntoView({ behavior: 'smooth', block: 'start' });
366	        card.querySelector('.notes-card-textarea')?.focus();
367	    }
368	
369	    // ---- Build sidebar (uses handleSidebarClick defined above) ----
370	    sidebar = buildSidebar(projects, handleSidebarClick);

371	    layout.appendChild(sidebar);
372	
373	    // ---- Populate main panel with cards for non-empty notes ----
374	    for (const project of projects) {
375	        for (const ws of project.workspaces) {
376	            if (ws.notes) {
377	                const card = buildNoteCard(
378	                    project.projectId,
379	                    project.projectName,
380	                    ws.workspaceId,
381	                    ws.notes,
382	                    handleSave,
383	                    () => handleCardEmpty(project.projectId, ws.workspaceId),
384	                );
385	                mainPanel.appendChild(card);
386	            }
387	        }
388	    }
389	
390	    refreshEmptyState(mainPanel);
391	    layout.appendChild(mainPanel);
392	    container.appendChild(layout);
393	}

